  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah gardu listrik PLN memiliki 10 unit kapasitor. Peluang sebuah kapasitor mengalami kerusakan dalam setahun adalah 0.1. Berapakah probabilitas tepat 2 dari 10 kapasitor tersebut rusak dalam setahun? (Gunakan distribusi binomial)','[{"key": "A", "text": "0.1937"}, {"key": "B", "text": "0.2512"}, {"key": "C", "text": "0.3020"}, {"key": "D", "text": "0.0574"}]'::jsonb,'A','','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang analis data PLN ingin menguji apakah ada perbedaan signifikan rata-rata konsumsi listrik antara pelanggan di wilayah perkotaan dan perdesaan. Metode uji hipotesis yang paling sesuai untuk digunakan adalah...','[{"key": "A", "text": "Uji Chi-Square"}, {"key": "B", "text": "Uji-t (t-test)"}, {"key": "C", "text": "Analisis Korelasi"}, {"key": "D", "text": "Regresi Linier"}]'::jsonb,'A','','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Rata-rata terjadi 3 kali pemadaman listrik di suatu kota setiap bulannya. Berapakah probabilitas tidak terjadi pemadaman sama sekali pada bulan depan? (Gunakan distribusi Poisson)','[{"key": "A", "text": "e-3"}, {"key": "B", "text": "e-1"}, {"key": "C", "text": "1 – e-3"}, {"key": "D", "text": "3 x e-3"}]'::jsonb,'B','','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'PLN ingin memprediksi beban listrik puncak (dalam MW) berdasarkan suhu harian (dalam °C). Model regresi linier sederhana yang dihasilkan adalah: Beban = 1500 + 50 * Suhu. Jika suhu hari ini diperkirakan 30°C, maka prediksi beban puncaknya adalah...','[{"key": "A", "text": "2500 MW"}, {"key": "B", "text": "3000 MW"}, {"key": "C", "text": "1550 MW"}, {"key": "D", "text": "1650 MW"}]'::jsonb,'A','','AKDING',4);
