  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi daya listrik sesaat (P) terhadap waktu (t) dinyatakan dengan P(t) = 3t2 + 4t. Total energi yang digunakan dari t=0 hingga t=2 detik adalah integral dari P(t) dt. Berapakah total energinya?','[{"key": "A", "text": "12"}, {"key": "B", "text": "16"}, {"key": "C", "text": "20"}, {"key": "D", "text": "24"}]'::jsonb,'B','','AKDING',9);
