  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Biaya operasional sebuah pembangkit listrik dinyatakan oleh fungsi C(x) = x2 - 20x + 500, dimana x adalah output daya dalam MWh. Untuk mencapai biaya operasional minimum, berapa output daya yang harus dihasilkan?','[{"key": "A", "text": "5 MWh"}, {"key": "B", "text": "10 MWh"}, {"key": "C", "text": "15 MWh"}, {"key": "D", "text": "20 MWh"}]'::jsonb,'C','','AKDING',11);
