  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam uji hipotesis untuk menguji efektivitas program hemat energi baru, seorang analis PLN mendapatkan nilai p-value sebesar 0.02. Jika tingkat signifikansi (α) yang digunakan adalah 0.05, kesimpulan yang paling tepat adalah...','[{"key": "A", "text": "Program tidak efektif, hipotesis nol diterima."}, {"key": "B", "text": "Program efektif, ada cukup bukti untuk menolak hipotesis nol."}, {"key": "C", "text": "Hasilnya tidak signifikan karena p-value sangat kecil."}, {"key": "D", "text": "Perlu dilakukan uji ulang dengan sampel yang lebih besar."}]'::jsonb,'B','','AKDING',1);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Seorang analis menemukan korelasi positif yang kuat antara penjualan es krim dan beban puncak listrik di musim kemarau. Pernyataan yang paling tepat menggambarkan hubungan ini adalah...','[{"key": "A", "text": "Peningkatan penjualan es krim menyebabkan peningkatan beban listrik."}, {"key": "B", "text": "Peningkatan beban listrik menyebabkan orang membeli lebih banyak es krim."}, {"key": "C", "text": "Terdapat variabel ketiga (suhu panas) yang mempengaruhi keduanya, ini bukan hubungan sebab-akibat langsung."}, {"key": "D", "text": "Hubungan tersebut hanyalah kebetulan dan tidak memiliki makna statistik."}]'::jsonb,'C','','AKDING',2);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Distribusi Poisson sering digunakan dalam pemodelan kejadian di PLN. Karakteristik utama dari suatu proses yang dapat dimodelkan dengan distribusi Poisson adalah...','[{"key": "A", "text": "Jumlah percobaan harus tetap dan terbatas."}, {"key": "B", "text": "Probabilitas keberhasilan dan kegagalan harus sama."}, {"key": "C", "text": "Kejadian terjadi secara acak dan independen dalam interval waktu atau ruang tertentu."}, {"key": "D", "text": "Hasil dari setiap percobaan hanya ada dua (misalnya sukses atau gagal)."}]'::jsonb,'C','','AKDING',3);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam model regresi untuk peramalan beban, nilai R-squared (koefisien determinasi) yang tinggi (misalnya 0.92) mengindikasikan bahwa...','[{"key": "A", "text": "Prediksi model pasti 92% akurat."}, {"key": "B", "text": "92% dari variasi variabel dependen (beban listrik) dapat dijelaskan oleh variabel independen (misalnya suhu)."}, {"key": "C", "text": "Model tersebut terlalu sederhana dan perlu ditambahkan lebih banyak variabel."}, {"key": "D", "text": "Terdapat 8% kesalahan dalam pengumpulan data."}]'::jsonb,'B','','AKDING',4);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Uji Chi-Square adalah metode statistik yang paling sesuai digunakan untuk...','[{"key": "A", "text": "Membandingkan rata-rata konsumsi listrik antara dua wilayah."}, {"key": "B", "text": "Menguji apakah ada hubungan atau asosiasi antara dua variabel kategorikal (misalnya, kategori pelanggan dan jenis keluhan)."}, {"key": "C", "text": "Memprediksi konsumsi listrik bulanan berdasarkan jumlah anggota keluarga."}, {"key": "D", "text": "Mengelompokkan pelanggan berdasarkan pola pemakaian listrik."}]'::jsonb,'B','','AKDING',5);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari berikut ini yang BUKAN merupakan karakteristik dari Distribusi Normal?','[{"key": "A", "text": "Kurva berbentuk lonceng dan simetris terhadap nilai rata-rata."}, {"key": "B", "text": "Mean, median, dan modus berada pada titik yang sama."}, {"key": "C", "text": "Luas total di bawah kurva sama dengan 1."}, {"key": "D", "text": "Kurva hanya memiliki nilai positif dan condong ke kanan (positively skewed)."}]'::jsonb,'D','','AKDING',6);
