  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Alasan utama mengapa metode numerik diperlukan dalam sains dan teknik, termasuk di bidang ketenagalistrikan, adalah karena...','[{"key": "A", "text": "Metode analitik selalu menghasilkan jawaban yang salah."}, {"key": "B", "text": "Banyak masalah di dunia nyata terlalu kompleks untuk diselesaikan secara analitik (eksak)."}, {"key": "C", "text": "Komputer tidak dapat memahami rumus matematika."}, {"key": "D", "text": "Metode numerik lebih cepat daripada metode analitik."}]'::jsonb,'B','','AKDING',23);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Konsep dasar dari interpolasi adalah...','[{"key": "A", "text": "Memperkirakan nilai di luar rentang data yang diketahui."}, {"key": "B", "text": "Menemukan fungsi yang paling cocok (best fit) untuk keseluruhan data."}, {"key": "C", "text": "Memperkirakan nilai di antara titik-titik data yang diketahui."}, {"key": "D", "text": "Menghitung integral dari suatu fungsi."}]'::jsonb,'C','','AKDING',24);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam metode numerik iteratif, istilah "konvergensi" berarti...','[{"key": "A", "text": "Algoritma berhenti karena telah mencapai batas maksimum iterasi."}, {"key": "B", "text": "Solusi aproksimasi semakin mendekati solusi eksak seiring bertambahnya iterasi."}, {"key": "C", "text": "Kesalahan (error) pada setiap iterasi semakin membesar."}, {"key": "D", "text": "Algoritma menemukan beberapa solusi yang berbeda."}]'::jsonb,'B','','AKDING',25);
