  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Perbedaan fundamental antara Supervised Learning dan Unsupervised Learning adalah...','[{"key": "A", "text": "Supervised Learning menggunakan data berlabel, sedangkan Unsupervised Learning menggunakan data tanpa label."}, {"key": "B", "text": "Supervised Learning lebih rumit, sedangkan Unsupervised Learning lebih sederhana."}, {"key": "C", "text": "Supervised Learning untuk data besar, sedangkan Unsupervised Learning untuk data kecil."}, {"key": "D", "text": "Supervised Learning dilakukan oleh manusia, sedangkan Unsupervised Learning oleh mesin."}]'::jsonb,'A','','AKDING',27);
