  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dalam machine learning, tujuan utama membagi dataset menjadi training set dan testing set adalah untuk...','[{"key": "A", "text": "Mempercepat proses pelatihan model."}, {"key": "B", "text": "Mengurangi jumlah data yang perlu diproses."}, {"key": "C", "text": "Melatih model pada satu set data dan menguji kinerjanya pada data baru yang belum pernah dilihat."}, {"key": "D", "text": "Memastikan semua data digunakan dalam pelatihan."}]'::jsonb,'C','','AKDING',29);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah model machine learning yang dapat memprediksi secara akurat apakah email yang masuk adalah ''spam'' atau ''bukan spam'' merupakan contoh dari tugas...','[{"key": "A", "text": "Regresi"}, {"key": "B", "text": "Klasifikasi"}, {"key": "C", "text": "Clustering"}, {"key": "D", "text": "Reduksi Dimensi"}]'::jsonb,'B','','AKDING',30);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Istilah yang digunakan ketika sebuah model machine learning bekerja sangat baik pada data training tetapi performanya buruk pada data baru (testing) adalah...','[{"key": "A", "text": "Underfitting"}, {"key": "B", "text": "Overfitting"}, {"key": "C", "text": "Bias"}, {"key": "D", "text": "Akurasi"}]'::jsonb,'B','','AKDING',31);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Manakah dari tugas berikut di PLN yang paling cocok diselesaikan dengan algoritma Clustering?','[{"key": "A", "text": "Memprediksi beban listrik puncak untuk esok hari."}, {"key": "B", "text": "Mengidentifikasi anomali atau pencurian listrik dari pola pemakaian."}, {"key": "C", "text": "Mengelompokkan pelanggan ke dalam segmen-segmen berbeda berdasarkan pola konsumsi tanpa label awal."}, {"key": "D", "text": "Mengklasifikasikan jenis gangguan jaringan (misalnya, transien, permanen, temporer)."}]'::jsonb,'C','','AKDING',32);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Tujuan utama dari visualisasi data dalam proses analisis adalah untuk...','[{"key": "A", "text": "Membuat laporan terlihat lebih menarik secara estetika."}, {"key": "B", "text": "Menggantikan semua analisis statistik dengan gambar."}, {"key": "C", "text": "Membantu mengidentifikasi pola, tren, dan outlier dalam data dengan lebih mudah dan cepat."}, {"key": "D", "text": "Memenuhi persyaratan standar dalam pembuatan laporan."}]'::jsonb,'C','','AKDING',33);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Sebuah pie chart (diagram lingkaran) paling tepat digunakan ketika Anda ingin menunjukkan...','[{"key": "A", "text": "Tren data sepanjang waktu."}, {"key": "B", "text": "Hubungan antara dua variabel numerik."}, {"key": "C", "text": "Perbandingan komposisi atau proporsi dari suatu keseluruhan (misalnya, persentase energi dari berbagai jenis pembangkit)."}, {"key": "D", "text": "Distribusi frekuensi dari satu variabel numerik."}]'::jsonb,'C','','AKDING',34);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Fungsi utama dari Pivot Table dalam perangkat lunak spreadsheet atau analisis data adalah untuk...','[{"key": "A", "text": "Membuat grafik garis secara otomatis."}, {"key": "B", "text": "Membersihkan data dari nilai yang hilang (missing values)."}, {"key": "C", "text": "Meringkas, mengelompokkan, dan mengagregasi data tabular dalam jumlah besar secara interaktif."}, {"key": "D", "text": "Melakukan uji hipotesis statistik secara mendalam."}]'::jsonb,'C','','AKDING',35);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Kelebihan utama Box Plot dibandingkan dengan Bar Chart dalam menampilkan distribusi data adalah Box Plot dapat menunjukkan...','[{"key": "A", "text": "Hanya nilai rata-rata."}, {"key": "B", "text": "Hanya nilai maksimum dan minimum."}, {"key": "C", "text": "Ringkasan statistik lima serangkai (minimum, kuartil 1, median, kuartil 3, maksimum) dan outlier."}, {"key": "D", "text": "Jumlah total data."}]'::jsonb,'C','','AKDING',36);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Proses mengubah data konsumsi listrik per menit menjadi ringkasan data per jam dengan menghitung rata-ratanya disebut proses...','[{"key": "A", "text": "Filtering"}, {"key": "B", "text": "Normalisasi"}, {"key": "C", "text": "Agregasi"}, {"key": "D", "text": "Pivoting"}]'::jsonb,'C','','AKDING',37);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Mengapa identifikasi outlier (data pencilan) sangat penting dalam analisis data penggunaan listrik di PLN?','[{"key": "A", "text": "Karena outlier selalu merupakan data yang salah dan harus dihapus."}, {"key": "B", "text": "Outlier dapat mengindikasikan kejadian penting seperti kerusakan meteran, anomali jaringan, atau potensi pencurian listrik."}, {"key": "C", "text": "Outlier membuat visualisasi data menjadi tidak menarik."}, {"key": "D", "text": "Menghapus outlier akan selalu meningkatkan akurasi model prediksi."}]'::jsonb,'B','','AKDING',38);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Untuk memvisualisasikan kepadatan geografis laporan gangguan listrik di suatu kota, jenis visualisasi yang paling efektif adalah...','[{"key": "A", "text": "Line Chart"}, {"key": "B", "text": "Scatter Plot"}, {"key": "C", "text": "Heatmap (Peta Panas)"}, {"key": "D", "text": "Pie Chart"}]'::jsonb,'C','','AKDING',39);
  INSERT INTO public.questions (package_id,content,options,correct_answer,explanation,category,order_index) VALUES (pkg_id,'Dashboard bisnis intelijen (BI) yang baik bagi manajemen PLN idealnya berisi...','[{"key": "A", "text": "Tabel data mentah yang sangat besar dan detail."}, {"key": "B", "text": "Visualisasi ringkas dari Key Performance Indicators (KPIs) yang mudah dipahami."}, {"key": "C", "text": "Teks naratif yang panjang menjelaskan setiap temuan."}, {"key": "D", "text": "Hanya satu jenis grafik untuk konsistensi."}]'::jsonb,'B','','AKDING',40);
